def _types(dialect: str) -> dict[str, str]:
    if dialect == "postgres":
        return {
            "id": "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
            "ref": "BIGINT",
            "real": "DOUBLE PRECISION",
            "timestamp": "TIMESTAMP WITHOUT TIME ZONE",
            "boolean": "BOOLEAN",
        }
    return {
        "id": "INTEGER PRIMARY KEY AUTOINCREMENT",
        "ref": "INTEGER",
        "real": "REAL",
        "timestamp": "TEXT",
        "boolean": "INTEGER",
    }


