def _column_names(conn, table: str) -> set[str]:
    if conn.dialect == "sqlite":
        return {row["name"] for row in conn.execute(f"PRAGMA table_info({table})").fetchall()}
    rows = conn.execute(
        "SELECT column_name FROM information_schema.columns "
        "WHERE table_schema=current_schema() AND table_name=?",
        (table,),
    ).fetchall()
    return {row["column_name"] for row in rows}


def _upgrade_initial(conn) -> None:
    conn.executescript(_initial_schema(conn.dialect))
    # Adopta instalaciones SQLite anteriores sin volver a ALTERar en cada arranque.
    if conn.dialect == "sqlite":
        for table, columns in LEGACY_COLUMNS.items():
            present = _column_names(conn, table)
            for column, declaration in columns.items():
                if column not in present:
                    conn.execute(
                        f"ALTER TABLE {table} ADD COLUMN {column} {declaration}"
                    )


def _downgrade_initial(conn) -> None:
    for table in (
        "documents", "copilot_recommendations", "portal_tokens",
        "scheduled_job_runs", "whatsapp_links", "product_events",
        "webhook_events", "document_sequences", "password_resets", "quotes",
        "expenses", "invoices", "jobs", "clients", "users", "businesses",
    ):
        conn.execute(f"DROP TABLE IF EXISTS {table}")


