SQLITE_TENANT_RELATIONS = (
    ("jobs", "client_id", "clients"),
    ("jobs", "worker_id", "workers"),
    ("invoices", "client_id", "clients"),
    ("quotes", "client_id", "clients"),
    ("quotes", "invoice_id", "invoices"),
    ("documents", "client_id", "clients"),
    ("documents", "invoice_id", "invoices"),
    ("portal_tokens", "client_id", "clients"),
)


def _sqlite_tenant_trigger(table: str, column: str, parent: str, event: str) -> str:
    name = f"{table}_{column}_same_business_{event.lower()}"
    timing = (
        f"BEFORE INSERT ON {table}"
        if event == "INSERT"
        else f"BEFORE UPDATE OF business_id, {column} ON {table}"
    )
    return f"""
CREATE TRIGGER IF NOT EXISTS {name}
{timing}
WHEN NEW.{column} IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM {parent}
    WHERE id=NEW.{column} AND business_id=NEW.business_id
)
BEGIN
    SELECT RAISE(ABORT, '{column} pertenece a otro negocio');
END;
"""


def _upgrade_tenant_integrity(conn) -> None:
    for statement in INDEXES:
        table = statement.split(" ON ", 1)[1].split("(", 1)[0].strip()
        if _table_exists(conn, table):
            conn.execute(statement)
    # Las instalaciones SQLite heredadas no pueden añadir FKs con ALTER TABLE.
    # Estos triggers aplican la misma restricción a sus relaciones multiempresa.
    if conn.dialect == "sqlite":
        for table, column, parent in SQLITE_TENANT_RELATIONS:
            if not _table_exists(conn, table) or not _table_exists(conn, parent):
                continue
            for event in ("INSERT", "UPDATE"):
                conn.executescript(
                    _sqlite_tenant_trigger(table, column, parent, event)
                )


def _downgrade_tenant_integrity(conn) -> None:
    if conn.dialect == "sqlite":
        for table, column, _parent in SQLITE_TENANT_RELATIONS:
            conn.execute(
                f"DROP TRIGGER IF EXISTS "
                f"{table}_{column}_same_business_insert"
            )
            conn.execute(
                f"DROP TRIGGER IF EXISTS "
                f"{table}_{column}_same_business_update"
            )
    for statement in reversed(INDEXES):
        name = statement.split("INDEX IF NOT EXISTS ", 1)[1].split(" ", 1)[0]
        conn.execute(f"DROP INDEX IF EXISTS {name}")


def _upgrade_whatsapp_outbox(conn) -> None:
    t = _types(conn.dialect)
    conn.executescript(
        f"""
CREATE TABLE IF NOT EXISTS whatsapp_outbox (
    id                  {t["id"]},
    business_id         {t["ref"]} REFERENCES businesses(id),
    to_phone            TEXT NOT NULL,
    message_type        TEXT NOT NULL,
    text_body           TEXT,
    template_name       TEXT,
    template_language   TEXT,
    template_params     TEXT,
    idempotency_key     TEXT UNIQUE,
    status              TEXT NOT NULL DEFAULT 'queued',
    attempts            INTEGER NOT NULL DEFAULT 0,
    max_attempts        INTEGER NOT NULL DEFAULT 5,
    next_attempt_at     {t["timestamp"]} NOT NULL,
    locked_at           {t["timestamp"]},
    meta_message_id     TEXT UNIQUE,
    last_error          TEXT,
    sent_at             {t["timestamp"]},
    delivered_at        {t["timestamp"]},
    read_at             {t["timestamp"]},
    created_at          {t["timestamp"]} NOT NULL,
    updated_at          {t["timestamp"]} NOT NULL,
    CHECK (message_type IN ('text', 'template')),
    CHECK (status IN ('queued', 'processing', 'retrying', 'sent',
                      'delivered', 'read', 'failed'))
);
"""
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_whatsapp_outbox_due "
        "ON whatsapp_outbox(status, next_attempt_at)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_whatsapp_outbox_business "
        "ON whatsapp_outbox(business_id, created_at)"
    )


def _downgrade_whatsapp_outbox(conn) -> None:
    conn.execute("DROP INDEX IF EXISTS idx_whatsapp_outbox_business")
    conn.execute("DROP INDEX IF EXISTS idx_whatsapp_outbox_due")
    conn.execute("DROP TABLE IF EXISTS whatsapp_outbox")


def _upgrade_panel_layout(conn) -> None:
    # Guarda cómo cada negocio ordena/oculta los bloques de su panel de inicio.
    if "panel_layout" not in _column_names(conn, "businesses"):
        conn.execute("ALTER TABLE businesses ADD COLUMN panel_layout TEXT")


def _downgrade_panel_layout(conn) -> None:
    # SQLite no soporta DROP COLUMN en versiones antiguas; se deja la columna
    # (es nullable y opcional, no rompe nada al revertir).
    if conn.dialect != "sqlite":
        conn.execute("ALTER TABLE businesses DROP COLUMN IF EXISTS panel_layout")


def _table_exists(conn, table: str) -> bool:
    if conn.dialect == "sqlite":
        row = conn.execute(
            "SELECT 1 AS found FROM sqlite_master "
            "WHERE type='table' AND name=?",
            (table,),
        ).fetchone()
    else:
        row = conn.execute(
            "SELECT 1 AS found FROM information_schema.tables "
            "WHERE table_schema=current_schema() AND table_name=?",
            (table,),
        ).fetchone()
    return bool(row)


def _postgres_constraint_exists(conn, name: str) -> bool:
    if conn.dialect != "postgres":
        return False
    row = conn.execute(
        "SELECT 1 AS found FROM pg_constraint c "
        "JOIN pg_namespace n ON n.oid=c.connamespace "
        "WHERE n.nspname=current_schema() AND c.conname=?",
        (name,),
    ).fetchone()
    return bool(row)


def _upgrade_team_clockins(conn) -> None:
    t = _types(conn.dialect)
    conn.executescript(
        f"""
CREATE TABLE IF NOT EXISTS workers (
    id          {t["id"]},
    business_id {t["ref"]} NOT NULL REFERENCES businesses(id),
    name        TEXT NOT NULL,
    phone       TEXT,
    phone_norm  TEXT,
    color       TEXT,
    access_code TEXT NOT NULL,
    pin_hash    TEXT,
    active      {t["boolean"]} NOT NULL DEFAULT TRUE,
    created_at  {t["timestamp"]} NOT NULL,
    UNIQUE (business_id, id),
    UNIQUE (business_id, access_code)
);
"""
    )
    if "worker_id" not in _column_names(conn, "jobs"):
        conn.execute(f"ALTER TABLE jobs ADD COLUMN worker_id {t['ref']}")

    # La FK compuesta de fichajes necesita una clave única por negocio en jobs.
    for statement in INDEXES:
        table = statement.split(" ON ", 1)[1].split("(", 1)[0].strip()
        if _table_exists(conn, table):
            conn.execute(statement)

    if conn.dialect == "postgres" and not _postgres_constraint_exists(
        conn, "jobs_worker_same_business"
    ):
        conn.execute(
            "ALTER TABLE jobs ADD CONSTRAINT jobs_worker_same_business "
            "FOREIGN KEY (business_id, worker_id) "
            "REFERENCES workers(business_id, id)"
        )

    conn.executescript(
        f"""
CREATE TABLE IF NOT EXISTS worker_clockins (
    id          {t["id"]},
    business_id {t["ref"]} NOT NULL REFERENCES businesses(id),
    worker_id   {t["ref"]} NOT NULL,
    job_id      {t["ref"]},
    action      TEXT NOT NULL CHECK (action IN ('entrada', 'salida')),
    at          {t["timestamp"]} NOT NULL,
    source      TEXT NOT NULL CHECK (source IN ('web', 'whatsapp')),
    lat         {t["real"]},
    lng         {t["real"]},
    accuracy    {t["real"]},
    created_at  {t["timestamp"]} NOT NULL,
    FOREIGN KEY (business_id, worker_id)
        REFERENCES workers(business_id, id),
    FOREIGN KEY (business_id, job_id)
        REFERENCES jobs(business_id, id)
);

CREATE TABLE IF NOT EXISTS worker_tokens (
    token       TEXT PRIMARY KEY,
    business_id {t["ref"]} NOT NULL REFERENCES businesses(id),
    worker_id   {t["ref"]} NOT NULL,
    expires_at  {t["timestamp"]} NOT NULL,
    revoked     {t["boolean"]} NOT NULL DEFAULT FALSE,
    created_at  {t["timestamp"]} NOT NULL,
    FOREIGN KEY (business_id, worker_id)
        REFERENCES workers(business_id, id)
);
"""
    )
    for statement in INDEXES:
        table = statement.split(" ON ", 1)[1].split("(", 1)[0].strip()
        if _table_exists(conn, table):
            conn.execute(statement)

    if conn.dialect == "sqlite":
        for event in ("INSERT", "UPDATE"):
            conn.executescript(
                _sqlite_tenant_trigger("jobs", "worker_id", "workers", event)
            )


def _downgrade_team_clockins(conn) -> None:
    if conn.dialect == "sqlite":
        conn.execute("UPDATE jobs SET worker_id=NULL")
        conn.execute("DROP TRIGGER IF EXISTS jobs_worker_id_same_business_insert")
        conn.execute("DROP TRIGGER IF EXISTS jobs_worker_id_same_business_update")
    else:
        conn.execute(
            "ALTER TABLE jobs DROP CONSTRAINT IF EXISTS jobs_worker_same_business"
        )
    for name in (
        "idx_clockins_worker", "idx_jobs_worker", "idx_workers_business",
    ):
        conn.execute(f"DROP INDEX IF EXISTS {name}")
    conn.execute("DROP TABLE IF EXISTS worker_tokens")
    conn.execute("DROP TABLE IF EXISTS worker_clockins")
    conn.execute("DROP TABLE IF EXISTS workers")
    if conn.dialect != "sqlite":
        conn.execute("ALTER TABLE jobs DROP COLUMN IF EXISTS worker_id")


def _sqlite_rebuild_clockins_v6(conn) -> None:
    t = _types(conn.dialect)
    conn.executescript(
        f"""
CREATE TABLE worker_clockins_v6 (
    id          {t["id"]},
    business_id {t["ref"]} NOT NULL REFERENCES businesses(id),
    worker_id   {t["ref"]} NOT NULL,
    job_id      {t["ref"]},
    action      TEXT NOT NULL
                CHECK (action IN ('entrada', 'salida', 'pausa', 'reanudar')),
    at          {t["timestamp"]} NOT NULL,
    source      TEXT NOT NULL CHECK (source IN ('web', 'whatsapp')),
    lat         {t["real"]},
    lng         {t["real"]},
    accuracy    {t["real"]},
    created_at  {t["timestamp"]} NOT NULL,
    seal        TEXT,
    prev_seal   TEXT,
    FOREIGN KEY (business_id, worker_id)
        REFERENCES workers(business_id, id),
    FOREIGN KEY (business_id, job_id)
        REFERENCES jobs(business_id, id)
);
INSERT INTO worker_clockins_v6
    (id, business_id, worker_id, job_id, action, at, source, lat, lng,
     accuracy, created_at)
SELECT id, business_id, worker_id, job_id, action, at, source, lat, lng,
       accuracy, created_at
FROM worker_clockins;
DROP TABLE worker_clockins;
ALTER TABLE worker_clockins_v6 RENAME TO worker_clockins;
"""
    )


def _backfill_clockin_seals(conn) -> None:
    rows = conn.execute(
        "SELECT * FROM worker_clockins "
        "ORDER BY business_id, worker_id, id"
    ).fetchall()
    previous: dict[tuple[int, int], str | None] = {}
    for row in rows:
        key = (int(row["business_id"]), int(row["worker_id"]))
        prev_seal = previous.get(key)
        seal = clockin_seal(row, prev_seal)
        conn.execute(
            "UPDATE worker_clockins SET prev_seal=?, seal=? "
            "WHERE id=? AND business_id=?",
            (prev_seal, seal, row["id"], row["business_id"]),
        )
        previous[key] = seal


def _install_clockin_append_only(conn) -> None:
    if conn.dialect == "sqlite":
        conn.executescript(
            """
CREATE TRIGGER IF NOT EXISTS worker_clockins_require_seal
BEFORE INSERT ON worker_clockins
WHEN NEW.seal IS NULL OR NEW.seal=''
BEGIN
    SELECT RAISE(ABORT, 'todo fichaje necesita sello');
END;
CREATE TRIGGER IF NOT EXISTS worker_clockins_append_only_update
BEFORE UPDATE ON worker_clockins
BEGIN
    SELECT RAISE(ABORT, 'los fichajes son inalterables');
END;
CREATE TRIGGER IF NOT EXISTS worker_clockins_append_only_delete
BEFORE DELETE ON worker_clockins
BEGIN
    SELECT RAISE(ABORT, 'los fichajes son inalterables');
END;
CREATE TRIGGER IF NOT EXISTS clockin_corrections_append_only_update
BEFORE UPDATE ON worker_clockin_corrections
BEGIN
    SELECT RAISE(ABORT, 'las correcciones son inalterables');
END;
CREATE TRIGGER IF NOT EXISTS clockin_corrections_append_only_delete
BEFORE DELETE ON worker_clockin_corrections
BEGIN
    SELECT RAISE(ABORT, 'las correcciones son inalterables');
END;
"""
        )
        return
    conn.execute(
        """
CREATE OR REPLACE FUNCTION noesis_clockins_append_only()
RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'los registros de jornada son inalterables';
END;
$$ LANGUAGE plpgsql
"""
    )
    for table in ("worker_clockins", "worker_clockin_corrections"):
        trigger = f"{table}_append_only"
        conn.execute(f"DROP TRIGGER IF EXISTS {trigger} ON {table}")
        conn.execute(
            f"CREATE TRIGGER {trigger} BEFORE UPDATE OR DELETE ON {table} "
            "FOR EACH ROW EXECUTE FUNCTION noesis_clockins_append_only()"
        )


def _upgrade_immutable_clockins(conn) -> None:
    t = _types(conn.dialect)
    if "clockin_policy" not in _column_names(conn, "businesses"):
        conn.execute("ALTER TABLE businesses ADD COLUMN clockin_policy TEXT")

    columns = _column_names(conn, "worker_clockins")
    if conn.dialect == "sqlite" and "seal" not in columns:
        _sqlite_rebuild_clockins_v6(conn)
    elif conn.dialect == "postgres":
        if "seal" not in columns:
            conn.execute("ALTER TABLE worker_clockins ADD COLUMN seal TEXT")
        if "prev_seal" not in columns:
            conn.execute("ALTER TABLE worker_clockins ADD COLUMN prev_seal TEXT")
        conn.execute(
            "ALTER TABLE worker_clockins "
            "DROP CONSTRAINT IF EXISTS worker_clockins_action_check"
        )
        conn.execute(
            "ALTER TABLE worker_clockins ADD CONSTRAINT "
            "worker_clockins_action_check CHECK "
            "(action IN ('entrada', 'salida', 'pausa', 'reanudar'))"
        )

    _backfill_clockin_seals(conn)
    if conn.dialect == "postgres":
        conn.execute("ALTER TABLE worker_clockins ALTER COLUMN seal SET NOT NULL")

    for statement in INDEXES:
        table = statement.split(" ON ", 1)[1].split("(", 1)[0].strip()
        if _table_exists(conn, table):
            conn.execute(statement)

    conn.executescript(
        f"""
CREATE TABLE IF NOT EXISTS worker_clockin_corrections (
    id             {t["id"]},
    business_id    {t["ref"]} NOT NULL REFERENCES businesses(id),
    clockin_id     {t["ref"]} NOT NULL,
    author_user_id {t["ref"]} NOT NULL REFERENCES users(id),
    reason         TEXT NOT NULL,
    status         TEXT NOT NULL DEFAULT 'corregido'
                   CHECK (status IN ('corregido', 'anulado')),
    old_at         {t["timestamp"]},
    new_at         {t["timestamp"]},
    created_at     {t["timestamp"]} NOT NULL,
    FOREIGN KEY (business_id, clockin_id)
        REFERENCES worker_clockins(business_id, id)
);
"""
    )
    for statement in INDEXES:
        table = statement.split(" ON ", 1)[1].split("(", 1)[0].strip()
        if _table_exists(conn, table):
            conn.execute(statement)
    _install_clockin_append_only(conn)


def _downgrade_immutable_clockins(conn) -> None:
    if conn.dialect == "sqlite":
        for trigger in (
            "worker_clockins_require_seal",
            "worker_clockins_append_only_update",
            "worker_clockins_append_only_delete",
            "clockin_corrections_append_only_update",
            "clockin_corrections_append_only_delete",
        ):
            conn.execute(f"DROP TRIGGER IF EXISTS {trigger}")
    else:
        for table in ("worker_clockins", "worker_clockin_corrections"):
            conn.execute(
                f"DROP TRIGGER IF EXISTS {table}_append_only ON {table}"
            )
        conn.execute("DROP FUNCTION IF EXISTS noesis_clockins_append_only()")
    conn.execute("DROP INDEX IF EXISTS idx_clockin_corrections_clockin")
    conn.execute("DROP TABLE IF EXISTS worker_clockin_corrections")
    # Las columnas y el CHECK ampliado se conservan: eliminarlos podría destruir
    # sellos o hacer imposible revertir si ya existen pausas.


