Migration = tuple[int, str, Callable, Callable]
MIGRATIONS: tuple[Migration, ...] = (
    (1, "esquema_inicial", _upgrade_initial, _downgrade_initial),
    (2, "integridad_multiempresa", _upgrade_tenant_integrity, _downgrade_tenant_integrity),
    (3, "cola_whatsapp_durable", _upgrade_whatsapp_outbox, _downgrade_whatsapp_outbox),
    (4, "panel_personalizable", _upgrade_panel_layout, _downgrade_panel_layout),
    (5, "equipo_fichaje", _upgrade_team_clockins, _downgrade_team_clockins),
    (6, "fichaje_inalterable", _upgrade_immutable_clockins, _downgrade_immutable_clockins),
    (7, "verifactu_fase1", _upgrade_verifactu_phase1, _downgrade_verifactu_phase1),
    (8, "backups_verificados", _upgrade_verified_backups, _downgrade_verified_backups),
    (9, "verifactu_fase2", _upgrade_verifactu_phase2, _downgrade_verifactu_phase2),
)
LATEST_VERSION = MIGRATIONS[-1][0]


def _ensure_version_table(conn) -> None:
    timestamp = _types(conn.dialect)["timestamp"]
    conn.execute(
        "CREATE TABLE IF NOT EXISTS schema_migrations ("
        "version INTEGER PRIMARY KEY, name TEXT NOT NULL, "
        f"applied_at {timestamp} NOT NULL)"
    )


def _version_table_exists(conn) -> bool:
    if conn.dialect == "sqlite":
        row = conn.execute(
            "SELECT 1 AS found FROM sqlite_master "
            "WHERE type='table' AND name='schema_migrations'"
        ).fetchone()
    else:
        row = conn.execute(
            "SELECT 1 AS found FROM information_schema.tables "
            "WHERE table_schema=current_schema() "
            "AND table_name='schema_migrations'"
        ).fetchone()
    return bool(row)


def _current_version(conn) -> int:
    if not _version_table_exists(conn):
        return 0
    row = conn.execute(
        "SELECT COALESCE(MAX(version), 0) AS version FROM schema_migrations"
    ).fetchone()
    return int(row["version"])


def current_version() -> int:
    from . import db

    with db.get_conn() as conn:
        return _current_version(conn)


def current_version_connection(conn) -> int:
    """Consulta la versión dentro de una conexión o esquema ya seleccionado."""
    return _current_version(conn)


def is_current() -> bool:
    try:
        return current_version() == LATEST_VERSION
    except Exception:
        return False


def upgrade_connection(conn, target: int | None = None) -> int:
    """Aplica migraciones sobre una conexión existente.

    La restauración de Postgres la usa con un ``search_path`` temporal para no
    escribir nunca en el esquema real durante la verificación.
    """
    target = LATEST_VERSION if target is None else target
    if target < 0 or target > LATEST_VERSION:
        raise ValueError(f"Versión objetivo no válida: {target}")
    _ensure_version_table(conn)
    current = _current_version(conn)
    for version, name, apply, _revert in MIGRATIONS:
        if current < version <= target:
            apply(conn)
            conn.execute(
                "INSERT INTO schema_migrations (version, name, applied_at) "
                "VALUES (?, ?, ?)",
                (version, name, datetime.now().isoformat(timespec="seconds")),
            )
            current = version
    return current


def upgrade(target: int | None = None) -> int:
    from . import db

    with db.get_conn() as conn:
        current = upgrade_connection(conn, target)
    return current


def downgrade(target: int | None = None) -> int:
    from . import db

    with db.get_conn() as conn:
        current = _current_version(conn)
        target = max(0, current - 1) if target is None else target
        if target < 0 or target >= current:
            raise ValueError(f"Versión objetivo no válida: {target}")
        for version, _name, _apply, revert in reversed(MIGRATIONS):
            if target < version <= current:
                revert(conn)
                conn.execute(
                    "DELETE FROM schema_migrations WHERE version=?", (version,)
                )
        return target


def main() -> None:
    parser = argparse.ArgumentParser(description="Migraciones de Noesis")
    parser.add_argument("action", choices=("upgrade", "downgrade", "current"))
    parser.add_argument("target", nargs="?", type=int)
    args = parser.parse_args()
    if args.action == "upgrade":
        version = upgrade(args.target)
    elif args.action == "downgrade":
        version = downgrade(args.target)
    else:
        version = current_version()
    print(f"Esquema en versión {version}/{LATEST_VERSION}")


if __name__ == "__main__":
    main()
